    /// <inheritdoc cref="Quaternion.op_Division(Quaternion, Quaternion)" />
    public static floatQuat operator /(floatQuat a, floatQuat b)
    {
        floatQuat ans;

        var ax = a.X;
        var ay = a.Y;
        var az = a.Z;
        var aw = a.W;

        //-------------------------------------
        // Inverse part.
        var ls = b.X * b.X + b.Y * b.Y + b.Z * b.Z + b.W * b.W;
        var invNorm = 1 / ls;

        var bx = -b.X * invNorm;
        var by = -b.Y * invNorm;
        var bz = -b.Z * invNorm;
        var bw = b.W * invNorm;

        //-------------------------------------
        // Multiply part.

        // cross(av, bv)
        var cx = ay * bz - az * by;
        var cy = az * bx - ax * bz;
        var cz = ax * by - ay * bx;

        var dot = ax * bx + ay * by + az * bz;

        ans.X = ax * bw + bx * aw + cx;
        ans.Y = ay * bw + by * aw + cy;
        ans.Z = az * bw + bz * aw + cz;
        ans.W = aw * bw - dot;

        return ans;
    }

